mapper.select:
select PTL_SEC_VALUTION.CDATE as cdate, PTL_SEC_VALUTION.PORTFOLIO_ID as portfolioId, PTL_SEC_VALUTION.FINPROD_ID as finprodId, PTL_SEC_VALUTION.INV_AIM as invAim, PTL_SEC_VALUTION.CCY as ccy, PTL_SEC_VALUTION.TDY_FLOAT_INGPL as tdyFloatIngpl, PTL_SEC_VALUTION.DSC_CLEAN_PRICE as dscCleanPrice, PTL_SEC_VALUTION.BUY_COST_AMT as buyCostAmt, PTL_SEC_VALUTION.BUY_CLEAN_PRICE as buyCleanPrice, PTL_SEC_VALUTION.MARKET_VALUE as marketValue, PTL_SEC_VALUTION.MARKET_CLEAN_PRICE as marketCleanPrice, PTL_SEC_VALUTION.TDY_DSCINCEXP_ADD as tdyDscincexpAdd, PTL_SEC_VALUTION.TDY_INTINCEXP_ADD as tdyIntincexpAdd, PTL_SEC_VALUTION.TDY_DSCLOSS_ADD as tdyDsclossAdd, PTL_SEC_VALUTION.TDY_FLOAT_INGPL_ADD as tdyFloatIngplAdd, PTL_SEC_VALUTION.TDY_FEE_ADD as tdyFeeAdd, PTL_SEC_VALUTION.ACCU_NET_VALUE as accuNetValue, PTL_SEC_VALUTION.CREATE_USER as createUser, PTL_SEC_VALUTION.CREATE_DEPT as createDept, PTL_SEC_VALUTION.CREATE_TIME as createTime, PTL_SEC_VALUTION.UPDATE_USER as updateUser, PTL_SEC_VALUTION.UPDATE_TIME as updateTime, PTL_SEC_VALUTION.ACT_D_YIELD as actDYield, PTL_SEC_VALUTION.SEC_ACCT_ID as secAcctId, nvl(PTL_SEC_VALUTION.DELAY_PAY_AMT,0) as delayPayAmt, PTL_SEC_VALUTION.B_CCY as bCcy, PTL_SEC_VALUTION.TDY_FLOAT_INGPL_B as tdyFloatIngplB, PTL_SEC_VALUTION.DSC_COST_AMT_B as dscCostAmtB, PTL_SEC_VALUTION.DSC_CLEAN_PRICE_B as dscCleanPriceB, PTL_SEC_VALUTION.DELAY_PAY_AMT_B as delayPayAmtB, PTL_SEC_VALUTION.TDY_INTINCEXP_B as tdyIntincexpB, PTL_SEC_VALUTION.IN_TDY_INTINCEXP as inTdyIntincexp, PTL_SEC_VALUTION.OUT_TDY_INTINCEXP as outTdyIntincexp, PTL_SEC_VALUTION.END_DAYS_1 as endDays1, PTL_SEC_VALUTION.END_DAYS_2 as endDays2, PTL_SEC_VALUTION.INT_RATE as intRate, PTL_SEC_VALUTION.TDY_DSCLOSS_ADD_B as tdyDsclossAddB, PTL_SEC_VALUTION.GEN_TYPE as genType, /*PTL_SEC_VALUTION.SHADOW_AMT as shadowAmt,*/ nvl(PTL_SEC_VALUTION.DSC_COST_AMT,0) as dscCostAmt, PTL_SEC_VALUTION.SHARE_AMT as shareAmt, PTL_SEC_VALUTION.TDY_INTINCEXP as tdyIntincexp, null as actDYield, null as finprodType2, PTL_SEC_VALUTION.yield as yield, nvl(PTL_SEC_VALUTION.DSC_COST_AMT,0) as accrualCost, PTL_SEC_VALUTION.SHARE_AMT as accrualAmt, PTL_SEC_VALUTION.TDY_INTINCEXP as accrualInt, fin_product_type.type_8 as tgAssetType from PTL_SEC_VALUTION LEFT JOIN FIN_PRODUCT_TYPE ON PTL_SEC_VALUTION.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID where 1=1
AND PTL_SEC_VALUTION.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND PTL_SEC_VALUTION.CDATE = to_date(#{cdate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
